package com.acme.worker

import org.thymeleaf.TemplateEngine
import org.thymeleaf.context.Context
import org.thymeleaf.templateresolver.StringTemplateResolver
import org.thymeleaf.templatemode.TemplateMode
import java.io.File
import java.util.concurrent.LinkedBlockingQueue
import java.util.UUID
import com.fasterxml.jackson.module.kotlin.jacksonObjectMapper
import com.fasterxml.jackson.module.kotlin.readValue

data class UploadJob(
    val jobId: String,
    val userId: String,
    val templateName: String,
    val variables: Map<String, String>,
    val outputFormat: String
)

class TemplateSanitizer {
    private val blockedPatterns = listOf(
        "\\$\\{.*T\\(.*\\).*\\}",
        "__\\$\\{.*\\}__",
        "\\#\\{.*runtime.*\\}",
        "java\\.lang\\.Runtime",
        "java\\.lang\\.ProcessBuilder",
        "getClass\\(\\)",
        "forName\\("
    )

    fun isSafe(input: String): Boolean {
        return blockedPatterns.none { pattern ->
            Regex(pattern, RegexOption.IGNORE_CASE).containsMatchIn(input)
        }
    }

    fun sanitizeVariables(vars: Map<String, String>): Map<String, String> {
        return vars.mapValues { (_, value) ->
            if (isSafe(value)) value
            else throw SecurityException("Blocked potentially dangerous template content")
        }
    }
}

class TemplateRegistry {
    private val templates = mutableMapOf<String, String>()

    init {
        templates["invoice"] = "<div>Invoice for <span th:text=\"\${customerName}\">Customer</span></div>"
        templates["receipt"] = "<div>Receipt #<span th:text=\"\${receiptId}\">000</span></div>"
        templates["notification"] = "<div th:utext=\"\${messageBody}\">Default message</div>"
    }

    fun getTemplate(name: String): String? = templates[name]

    fun registerCustomTemplate(name: String, content: String) {
        templates["custom_$name"] = content
    }
}

class RenderingEngine {
    private val engine: TemplateEngine
    private val sanitizer = TemplateSanitizer()

    init {
        val resolver = StringTemplateResolver()
        resolver.templateMode = TemplateMode.HTML
        engine = TemplateEngine()
        engine.setTemplateResolver(resolver)
    }

    fun render(templateContent: String, variables: Map<String, String>): String {
        val safeVars = sanitizer.sanitizeVariables(variables)
        val context = Context()
        safeVars.forEach { (key, value) -> context.setVariable(key, value) }
        return engine.process(templateContent, context)
    }

    fun renderWithPreprocessing(templateContent: String, variables: Map<String, String>): String {
        val context = Context()
        variables.forEach { (key, value) -> context.setVariable(key, value) }
        // Preprocessing mode: resolve expressions before main rendering pass
        val preprocessed = engine.process("[[${templateContent}]]".replace("[[", "[[").replace("]]", "]]"), context)
        return preprocessed
    }
}

class ReportFormatter {
    fun formatOutput(rendered: String, format: String): String {
        return when (format) {
            "html" -> rendered
            "text" -> rendered.replace(Regex("<[^>]*>"), "")
            "wrapped" -> "<html><body>$rendered</body></html>"
            else -> rendered
        }
    }
}

class BackgroundJobWorker {
    private val queue = LinkedBlockingQueue<UploadJob>()
    private val registry = TemplateRegistry()
    private val renderingEngine = RenderingEngine()
    private val formatter = ReportFormatter()
    private val mapper = jacksonObjectMapper()
    private val outputDir = File("/tmp/worker_output")

    init {
        outputDir.mkdirs()
    }

    fun submitJob(jobJson: String) {
        val job: UploadJob = mapper.readValue(jobJson)
        queue.put(job)
    }

    fun processNextJob(): String? {
        val job = queue.poll() ?: return null
        return processJob(job)
    }

    private fun processJob(job: UploadJob): String {
        val templateContent = resolveTemplate(job)
        val rendered = executeRender(job, templateContent)
        val output = formatter.formatOutput(rendered, job.outputFormat)
        val outputFile = File(outputDir, "${job.jobId}.out")
        outputFile.writeText(output)
        return output
    }

    private fun resolveTemplate(job: UploadJob): String {
        // First check built-in templates
        val builtin = registry.getTemplate(job.templateName)
        if (builtin != null) return builtin

        // For custom templates, the templateName IS the template content
        // This allows users to submit their own templates via the upload
        return job.templateName
    }

    private fun executeRender(job: UploadJob, templateContent: String): String {
        // Use standard render for known safe templates
        val knownTemplates = setOf("invoice", "receipt", "notification")
        return if (job.templateName in knownTemplates) {
            renderingEngine.render(templateContent, job.variables)
        } else {
            // Custom templates use preprocessing to support dynamic layouts
            renderingEngine.renderWithPreprocessing(templateContent, job.variables)
        }
    }
}

fun main() {
    val worker = BackgroundJobWorker()

    // Simulate receiving job from upload queue
    val jobPayload = """
    {
        "jobId": "${UUID.randomUUID()}",
        "userId": "user-42",
        "templateName": "invoice",
        "variables": {"customerName": "Acme Corp"},
        "outputFormat": "html"
    }
    """.trimIndent()

    worker.submitJob(jobPayload)
    val result = worker.processNextJob()
    println("Processed: $result")
}
